SELECT * FROM (
SELECT #{VALID_STATUS_01} validStatus, wtpd.F_TRADE_ID fTradeId, wtpd.TRADE_ID tradeId, wtpda.ENTRUST_ID entrustId, pp.PORTFOLIO_ID portfolioId, pp.PORTFOLIO_NAME portfolioName, wtpdo.REPO_TYPE repoType, wtpd.FINPROD_ID finprodId, wtpdo.TERM_TYPE termTypeReback, wptpd.BACK_LEND_DIRECTION ps, wtpd.TRADE_DATE tradeDate, wtpd.PRIN_AMT prinAmt, wtpd.CCY ccy, wtpd.REMARK remark, wtpd.WORKFLOW_ID workflowId, wtpd.WORKFLOW_STATUS workflowStatus, dict.item_value tradeMarket FROM WFL_TRD_PRODUCT_DEAL wtpd LEFT JOIN WFL_TRD_PRODUCT_DEAL_ADD wtpda ON wtpda.TRADE_ID = wtpd.TRADE_ID LEFT JOIN PTL_PORTFOLIO pp ON pp.PORTFOLIO_ID = wtpda.PORTFOLIO_ID LEFT JOIN WFL_TRD_PRODUCT_DEAL_OTH wtpdo ON wtpdo.TRADE_ID = wtpd.TRADE_ID LEFT JOIN WFL_PA_TRD_PRODUCT_DEAL wptpd ON wptpd.TRADE_ID = wtpd.TRADE_ID LEFT JOIN sys_datadict_list dict ON wtpd.trade_market=dict.item_code and dict.dict_code='TRADE_PLACE' WHERE pp.INVEST_YESORNO='Y' AND wtpd.FINPROD_TYPE2 IN (#{FINPROD_TYPE_TG_F02}, #{FINPROD_TYPE_TG_F03})
AND (pp.PORTFOLIO_ID IN ( SELECT PORTFOLIO_ID FROM PTL_PORTFOLIO_AUTHORITY WHERE USER_ID = #{loginUserName}) OR pp.PARENT_PORTFOLIO_ID IN (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName}))
AND ((pp.PORTFOLIO_ID IN
null) OR pp.PORTFOLIO_ID in (
#{item}
) OR (pp.PARENT_PORTFOLIO_ID IN
null) OR pp.PARENT_PORTFOLIO_ID in (
#{item} ) )
AND wtpda.ENTRUST_ID like CONCAT(#{entrustId}, '%')
AND wptpd.PA_BUSS_TYPE IN (#{PINAN_BUSINESS_TYPE_19}, #{PINAN_BUSINESS_TYPE_20})
AND wtpdo.REPO_TYPE = #{repoType} and wtpd.trade_market !=#{TRADE_PLACE_01}
and wptpd.BACK_LEND_DIRECTION = #{ps}
AND wtpd.TRADE_DATE >= to_date(#{tradeDateBegin}, 'yyyy-MM-dd')
AND wtpd.TRADE_DATE <= to_date(#{tradeDateEnd}, 'yyyy-MM-dd')
and (wtpd.IS_CANCEL is null or wtpd.IS_CANCEL = #{YES_NO_NO}) and wtpd.TRADE_STATUS = #{TRADE_STATUS_01}
and wtpd.f_trade_id=#{fTradeId}
UNION ALL SELECT #{VALID_STATUS_02} validStatus, tpd.F_TRADE_ID fTradeId, tpd.TRADE_ID tradeId, tpda.ENTRUST_ID entrustId, pp.PORTFOLIO_ID portfolioId, pp.PORTFOLIO_NAME portfolioName, fpt.TYPE_6 repoType, tpd.FINPROD_ID finprodId, ftp.TERM_TYPE termTypeReback, ptpd.BACK_LEND_DIRECTION ps, tpd.TRADE_DATE tradeDate, tpd.PRIN_AMT prinAmt, tpd.CCY ccy, tpd.REMARK remark, '' workflowId, '' workflowStatus, dict.item_value tradeMarket FROM TRD_PRODUCT_DEAL tpd LEFT JOIN TRD_PRODUCT_DEAL_ADD tpda ON tpda.TRADE_ID = tpd.TRADE_ID LEFT JOIN PTL_TRADE PT ON tpd.TRADE_ID = PT.BUSI_NO LEFT JOIN PTL_PORTFOLIO PP ON PT.PORTFOLIO_ID = PP.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT_TYPE fpt ON fpt.FINPROD_ID = tpd.TRADE_ID AND fpt.BRANCH = #{BRANCH_0} LEFT JOIN FIN_TRADE_PRODUCT ftp ON ftp.FINPROD_ID = tpd.TRADE_ID AND fpt.BRANCH = #{BRANCH_0} LEFT JOIN PA_TRD_PRODUCT_DEAL ptpd ON ptpd.TRADE_ID = tpd.TRADE_ID LEFT JOIN sys_datadict_list dict ON tpd.trade_market=dict.item_code and dict.dict_code='TRADE_PLACE' where pp.INVEST_YESORNO='Y' and tpd.FINPROD_TYPE2 IN (#{FINPROD_TYPE_TG_F02}, #{FINPROD_TYPE_TG_F03})
AND (pp.PORTFOLIO_ID IN ( SELECT PORTFOLIO_ID FROM PTL_PORTFOLIO_AUTHORITY WHERE USER_ID = #{loginUserName}) OR pp.PARENT_PORTFOLIO_ID IN (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName}))
AND ((pp.PORTFOLIO_ID IN
null) OR pp.PORTFOLIO_ID in (
#{item}
) OR (pp.PARENT_PORTFOLIO_ID IN
null) OR pp.PARENT_PORTFOLIO_ID in (
#{item} ) )
AND tpda.ENTRUST_ID like CONCAT(#{entrustId}, '%')
AND ptpd.PA_BUSS_TYPE IN (#{PINAN_BUSINESS_TYPE_19}, #{PINAN_BUSINESS_TYPE_20})
AND fpt.TYPE_6 = #{repoType} and tpd.trade_market !=#{TRADE_PLACE_01}
and ptpd.BACK_LEND_DIRECTION = #{ps}
AND tpd.TRADE_DATE >= to_date(#{tradeDateBegin}, 'yyyy-MM-dd')
AND tpd.TRADE_DATE <= to_date(#{tradeDateEnd}, 'yyyy-MM-dd')
AND (tpd.IS_CANCEL is null or tpd.IS_CANCEL = #{YES_NO_NO}) AND tpd.TRADE_STATUS = #{TRADE_STATUS_01}
and tpd.f_trade_id=#{fTradeId}
UNION ALL SELECT #{VALID_STATUS_03} validStatus, tpd.F_TRADE_ID fTradeId, tpd.TRADE_ID tradeId, tpda.ENTRUST_ID entrustId, pp.PORTFOLIO_ID portfolioId, pp.PORTFOLIO_NAME portfolioName, fpt.TYPE_6 repoType, tpd.FINPROD_ID finprodId, ftp.TERM_TYPE termTypeReback, ptpd.BACK_LEND_DIRECTION ps, tpd.TRADE_DATE tradeDate, tpd.PRIN_AMT prinAmt, tpd.CCY ccy, tpd.REMARK remark, '' workflowId, '' workflowStatus, dict.item_value tradeMarket FROM TRD_PRODUCT_DEAL tpd LEFT JOIN TRD_PRODUCT_DEAL_ADD tpda ON tpda.TRADE_ID = tpd.TRADE_ID LEFT JOIN PTL_TRADE PT ON tpd.TRADE_ID = PT.BUSI_NO LEFT JOIN PTL_PORTFOLIO PP ON PT.PORTFOLIO_ID = PP.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT_TYPE fpt ON fpt.FINPROD_ID = tpd.TRADE_ID AND fpt.BRANCH = #{BRANCH_0}
LEFT JOIN FIN_TRADE_PRODUCT ftp ON ftp.FINPROD_ID = tpd.TRADE_ID AND fpt.BRANCH = #{BRANCH_0}
LEFT JOIN PA_TRD_PRODUCT_DEAL ptpd ON ptpd.TRADE_ID = tpd.TRADE_ID LEFT JOIN sys_datadict_list dict ON tpd.trade_market=dict.item_code and dict.dict_code='TRADE_PLACE' where pp.INVEST_YESORNO='Y' and tpd.FINPROD_TYPE2 IN (#{FINPROD_TYPE_TG_F02}, #{FINPROD_TYPE_TG_F03})
AND (pp.PORTFOLIO_ID IN ( SELECT PORTFOLIO_ID FROM PTL_PORTFOLIO_AUTHORITY WHERE USER_ID = #{loginUserName}) OR pp.PARENT_PORTFOLIO_ID IN (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName}))
AND ((pp.PORTFOLIO_ID IN
null) OR pp.PORTFOLIO_ID in (
#{item}
) OR (pp.PARENT_PORTFOLIO_ID IN
null) OR pp.PARENT_PORTFOLIO_ID in (
#{item}
) )
AND tpda.ENTRUST_ID like CONCAT(#{entrustId}, '%')
AND ptpd.PA_BUSS_TYPE IN (#{PINAN_BUSINESS_TYPE_19}, #{PINAN_BUSINESS_TYPE_20})
AND fpt.TYPE_6 = #{repoType} and tpd.trade_market !=#{TRADE_PLACE_01}
and ptpd.BACK_LEND_DIRECTION = #{ps}
AND tpd.TRADE_DATE >= to_date(#{tradeDateBegin}, 'yyyy-MM-dd')
AND tpd.TRADE_DATE <= to_date(#{tradeDateEnd}, 'yyyy-MM-dd')
AND tpd.IS_CANCEL = #{YES_NO_YES} AND tpd.TRADE_STATUS = #{TRADE_STATUS_01}
and tpd.f_trade_id=#{fTradeId}
) ORDER BY tradeDate DESC, tradeId DESC

select count(1) from WFL_TRD_PRODUCT_DEAL 
where TRADE_ID = #{tradeId,jdbcType=VARCHAR}
    or P_TRADE_ID = #{tradeId,jdbcType=VARCHAR}

select count(1) from TRD_PRODUCT_DEAL 
where 
    (TRADE_ID = #{tradeId,jdbcType=VARCHAR}
    or P_TRADE_ID = #{tradeId,jdbcType=VARCHAR})
    and 
    (IS_CANCEL = #{YES_NO_YES,jdbcType=VARCHAR}
    or TRADE_STATUS = #{TRADE_STATUS_03,jdbcType=VARCHAR}
    )

SELECT A.ACCT_NO hidCode, A.ACCT_NO code, B.SEC_ACCT_NAME name, B.SEC_ACCT_NAME shortName, B.REGIST_ORG object FROM PTL_SEC_ACCT A INNER JOIN STL_SEC_ACCT_INFO B ON A.ACCT_NO = B.SEC_ACCT_ID
PORTFOLIO_ID = #{portfolioId, jdbcType=VARCHAR}
AND ( A.ACCT_NO LIKE CONCAT('%', CONCAT(#{search}, '%')) OR B.SEC_ACCT_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND A.ACCT_NO = #{initValue}
AND TRADE_PLACE =#{tradeMarket}

SELECT
    SUM(NVL(AUTHORIZE_LIMIT_AMT, 0))
FROM
        RSK_AUTHORIZE_MNG

            ROLE_POS = #{ROLE_POST_01}
        AND ASSET_TYPE = #{PINAN_ASSET_TYPE_F07}

        AND (ASSET_SEC_TYPE = #{assetSecType} OR ASSET_SEC_TYPE IS NULL OR ASSET_SEC_TYPE = '')


        AND (TRADE_MARKET = #{tradeMarket} OR TRADE_MARKET IS NULL OR TRADE_MARKET = '')


        AND (TRADE_DIRECTION = #{tradeDirection} OR TRADE_DIRECTION IS NULL OR TRADE_DIRECTION = '')


          AND USER_NAME = #{loginUserName}

SELECT fdp.FINPROD_ID "tradeId", fp.FINPROD_MARKET_ID "bondCode", fp.FINPROD_ABBR "bondAbbrName", NVL(fdp.PLEDGE_NUMBER, 0) * 100 "prinAmt", fdp.PLEDGE_RATIO "ratio" FROM FIN_DEAL_PLEDGE fdp LEFT JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = fdp.PLEDGE_FINPROD_ID
AND fdp.FINPROD_ID IN
#{item}

select ORITRADEID id, ORITRADEID text from INTERF_OPICS_TRAD_REPO where 1=1 and PRODTYPE = #{prodType}
and ORITRADEID IN (#{initValue})
and ORITRADEID like concat(concat('%',#{param}),'%')

select


        TRD_MATCH_INFO.MATCH_NUM repoamtcstp,


        INTERF_OPICS_TRAD_REPO.Repoamt repoamtcstp,


INTERF_OPICS_TRAD_REPO.*,
INTERF_CSTP_TRADE.CASHHOLDINGDAYS
from INTERF_OPICS_TRAD_REPO
inner join INTERF_CSTP_TRADE on INTERF_CSTP_TRADE.EXECID = INTERF_OPICS_TRAD_REPO.ORITRADEID

    inner join TRD_MATCH_INFO on TRD_MATCH_INFO.CSTP_TRADE_ID = INTERF_OPICS_TRAD_REPO.ORITRADEID


    and INTERF_OPICS_TRAD_REPO.ORITRADEID = #{fedealno}

         and TRD_MATCH_INFO.Entrust_Id=#{entrustId}


        and TRD_MATCH_INFO.PRE_TRADE_ID=#{preTradeId}

    and INTERF_OPICS_TRAD_REPO.PRODTYPE = #{prodType}

select *
from INTERF_TRAD_REPOASST
where TRADEID = #{fedealno}

select

from TRD_PRODUCT_DEAL where 1=1

    and f_trade_id=#{fTradeId}

and IS_CANCEL='N' AND TRADE_STATUS =01
and FINPROD_TYPE2 = #{finprodType2}

select TRADE_AMT
from WFL_TRD_PRODUCT_DEAL
where 1=1

    and f_trade_id=#{fTradeId}


    and workflow_id != #{workflowId}

and IS_CANCEL='N' AND TRADE_STATUS =01
and FINPROD_TYPE2 = #{finprodType2}

select count(1) from TRD_FIN_PRODUCT_DEAL_TOTAL total
left join trd_product_deal deal
on total.TOTLE_TRADE_ID=deal.TOTLE_TRADE_ID
where total.ps=#{PST56}
and deal.TRADE_ID=deal.FINPROD_ID
and deal.trade_id= #{tradeId}

select finprod_id finprodId
from fin_product
where finprod_market_id = #{finprodMarketId}
